import * as React from "react";

import { cn } from "../lib/utils";
import { normalizeCodeLanguage, tokenizeCode } from "./code-tokenizer";

import styles from "./code.module.css";

export type CodeProps = Omit<React.ComponentPropsWithoutRef<"code">, "children"> & {
  code?: string;
  language?: string;
  format?: "syntax" | "plain";
  lineNumbers?: boolean;
  highlight?: readonly number[];
  wrap?: boolean;
  maxLines?: number;
  maxHeight?: React.CSSProperties["maxHeight"];
  label?: string;
} & ({ block?: false; children?: React.ReactNode } | { block: true; children?: string });
export function Code({
  children,
  code,
  block = false,
  language = "text",
  format = "syntax",
  lineNumbers = false,
  highlight = [],
  wrap = false,
  maxLines,
  maxHeight,
  label,
  className,
  style,
  ref,
  ...props
}: CodeProps & { ref?: React.Ref<HTMLElement> }) {
  if (!block)
    return (
      <code
        ref={ref}
        data-slot="code"
        className={cn(styles.code, styles.inline, className)}
        style={style}
        {...props}
      >
        {code ?? children}
      </code>
    );
  const value = code ?? (typeof children === "string" ? children : "");
  return (
    <pre
      data-slot="code-block-content"
      tabIndex={0}
      role="region"
      aria-label={label ?? `${language} code`}
      data-scroll-fade="both"
      className={cn(styles.code, styles.block, wrap && styles.wrap, className)}
      style={{
        maxHeight:
          maxHeight ??
          (maxLines ? `calc(${maxLines} * 1lh + 2 * var(--cipher-space-surface-inset))` : undefined),
        ...style
      }}
    >
      <code ref={ref} data-language={normalizeCodeLanguage(language)} {...props}>
        {value.split("\n").map((line, index, lines) => (
          <React.Fragment key={index}>
            <span className={cn(styles.line, highlight.includes(index + 1) && styles.highlight)}>
              {lineNumbers && (
                <span aria-hidden="true" className={styles.number}>
                  {index + 1}
                </span>
              )}
              {tokenizeCode(line, format === "plain" ? "plain" : language).map(
                (token, tokenIndex) => (
                  <span key={tokenIndex} className={styles[`token_${token.kind}`]}>
                    {token.text}
                  </span>
                )
              )}
            </span>
            {index < lines.length - 1 ? "\n" : null}
          </React.Fragment>
        ))}
      </code>
    </pre>
  );
}
Code.displayName = "Code";
